-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                  AS \"Report Date\",     CASE WHEN TRUNC(SYSDATE) &gt;= NVL(sd.START_DATE, TRUNC(SYSDATE)) AND TRUNC(SYSDATE) &lt;= NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999) THEN 'ACTIVE'             WHEN sd.START_DATE &gt; TRUNC(SYSDATE)                 THEN 'FUTURE'     END                                                 AS \"Record Status\",      pim.DEPT                                        AS \"Dept No\",     d.DEPT_NAME                                     AS \"Dept Name\",     pim.CLASS                                       AS \"Class No\",     c.CLASS_NAME                                    AS \"Class Name\",     pim.SUBCLASS                                    AS \"Subclass No\",     sc.SUB_NAME                                     AS \"Subclass Name\",     sd.ITEM                                         AS \"Primary Item ID\",     pim.ITEM_DESC                                   AS \"Primary Item DESC\",     pim.STANDARD_UOM                                AS \"Primary UOM\",     pim.STATUS                                      AS \"Primary Item Status\",     pim.PACK_IND                                    AS \"Primary Pack IND\",     pim.SELLABLE_IND                                AS \"Primary Sellable IND\",     pil.STATUS                                      AS \"Primary LOC Status\",     CASE pil.STATUS             WHEN 'A'                 THEN 'Active'             WHEN 'C'                 THEN 'Discontinued'             WHEN 'I'                 THEN 'Inactive'             WHEN 'D'                 THEN 'Delete'     END                                                 AS \"Primary LOC Status DESC\",      pils.STOCK_ON_HAND                              AS \"Primary Soh\",     pils.AV_COST                                    AS \"Primary Wac\",     pil.SELLING_UNIT_RETAIL                         AS \"Primary Retail\",     ROUND(NVL(pils.STOCK_ON_HAND, 0) * NVL(pils.AV_COST, 0), 2)AS \"Primary Soh Value\",     sd.LOCATION                                     AS \"Location ID\",     sd.LOC_TYPE                                     AS \"LOC Type\",     CASE sd.LOC_TYPE             WHEN 'S'                 THEN 'Store'             WHEN 'W'                 THEN 'Warehouse'     END                                                 AS \"LOC Type DESC\",      CASE sd.LOC_TYPE             WHEN 'S'                 THEN st.STORE_NAME             WHEN 'W'                 THEN wh.WH_NAME     END                                                 AS location_name,      sd.SUB_ITEM                                     AS \"Sub Item ID\",     sim.ITEM_DESC                                   AS \"Sub Item DESC\",     sim.STANDARD_UOM                                AS \"Sub Item UOM\",     sim.STATUS                                      AS \"Sub Item Status\",     sim.DEPT                                        AS \"Sub Item Dept\",     sim.PACK_IND                                    AS \"Sub Pack IND\",     sim.SELLABLE_IND                                AS \"Sub Sellable IND\",     sil.STATUS                                      AS \"Sub LOC Status\",     CASE sil.STATUS             WHEN 'A'                 THEN 'Active'             WHEN 'C'                 THEN 'Discontinued'             WHEN 'I'                 THEN 'Inactive'             WHEN 'D'                 THEN 'Delete'     END                                                 AS \"Sub LOC Status DESC\",      sils.STOCK_ON_HAND                              AS \"Sub Soh\",     sils.AV_COST                                    AS \"Sub Wac\",     sil.SELLING_UNIT_RETAIL                         AS \"Sub Retail\",     ROUND(NVL(sils.STOCK_ON_HAND, 0) * NVL(sils.AV_COST, 0), 2)AS \"Sub Soh Value\",     ROUND(NVL(sil.SELLING_UNIT_RETAIL, 0) - NVL(pil.SELLING_UNIT_RETAIL, 0), 2)AS \"Retail Price Variance\",     CASE             WHEN NVL(pil.SELLING_UNIT_RETAIL, 0) &gt; 0                 THEN ROUND((NVL(sil.SELLING_UNIT_RETAIL, 0) - NVL(pil.SELLING_UNIT_RETAIL, 0)) / pil.SELLING_UNIT_RETAIL * 100, 2)     END                                                 AS \"Retail Variance PCT\",      sd.START_DATE                                   AS \"Sub Start Date\",     sd.END_DATE                                     AS \"Sub End Date\",     TRUNC(SYSDATE) - TRUNC(NVL(sd.START_DATE, SYSDATE))AS \"Days Active\",     TRUNC(NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999)) - TRUNC(SYSDATE)AS \"Days Remaining\",     CASE WHEN sd.END_DATE IS NOT NULL AND sd.END_DATE BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + 7 THEN 'EXPIRING IN 7 DAYS'     END                                                 AS \"Expiry Status\",      sd.SUBSTITUTE_REASON                            AS \"Substitute Reason\",     CASE sd.SUBSTITUTE_REASON             WHEN 'O'                 THEN 'Out of Stock'             WHEN 'D'                 THEN 'Discontinued'             WHEN 'S'                 THEN 'Seasonal Replacement'             WHEN 'P'                 THEN 'Promotional Substitute'             ELSE NVL(sd.SUBSTITUTE_REASON, 'Not Specified')     END                                                 AS \"Substitute Reason DESC\",      ril.REPL_METHOD                                 AS \"Repl Method\",     CASE ril.REPL_METHOD             WHEN 'C'                 THEN 'Constant'             WHEN 'D'                 THEN 'Dynamic'             WHEN 'F'                 THEN 'Floating Point'             WHEN 'M'                 THEN 'Min/Max'             WHEN 'T'                 THEN 'Time Supply'             WHEN 'SO'                 THEN 'Store Orders'             WHEN 'DI'                 THEN 'Dynamic - Issues'             WHEN 'S'                 THEN 'Dynamic - Seasonal'             WHEN 'TI'                 THEN 'Time Supply - Issues'             WHEN 'E'                 THEN 'Time Supply - Seasonal'             ELSE NVL(ril.REPL_METHOD, 'NOT ON REPLENISHMENT')     END                                                 AS \"Repl Method DESC\",      ril.STOCK_CAT                                   AS \"Stock Category\",     CASE ril.STOCK_CAT             WHEN 'C'                 THEN 'Cross-Docked'             WHEN 'D'                 THEN 'Direct to Store'             WHEN 'L'                 THEN 'WH/Cross Link'             WHEN 'W'                 THEN 'Warehouse Stocked'             WHEN 'X'                 THEN 'PO Cross-link'             ELSE ril.STOCK_CAT     END                                                 AS \"Stock Category DESC\",      ril.REPL_ORDER_CTRL                             AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL             WHEN 'A'                 THEN 'Automatic'             WHEN 'B'                 THEN 'Buyer Worksheet'             WHEN 'M'                 THEN 'Manual'             WHEN 'S'                 THEN 'Semi-Automatic'     END                                                 AS \"Order Control DESC\",      ril.PRIMARY_REPL_SUPPLIER                       AS \"Repl Supplier ID\",     sp.SUP_NAME                                     AS \"Supplier Name\",     ril.MIN_STOCK                                   AS \"Min Stock\",     ril.MAX_STOCK                                   AS \"Max Stock\",     ril.SOURCE_WH                                   AS \"Source Warehouse\",     ril.PRIMARY_PACK_NO                             AS \"Primary Repl Pack\",     sril.REPL_METHOD                                AS \"Sub Repl Method\",     CASE sril.REPL_METHOD             WHEN 'C'                 THEN 'Constant'             WHEN 'D'                 THEN 'Dynamic'             WHEN 'F'                 THEN 'Floating Point'             WHEN 'M'                 THEN 'Min/Max'             WHEN 'T'                 THEN 'Time Supply'             WHEN 'SO'                 THEN 'Store Orders'             ELSE NVL(sril.REPL_METHOD, 'NOT ON REPLENISHMENT')     END                                                 AS \"Sub Repl Method DESC\",      sril.REPL_ORDER_CTRL                            AS \"Sub Order Control\",     CASE WHEN sd.END_DATE IS NOT NULL AND sd.END_DATE &lt; TRUNC(SYSDATE) THEN 'EXPIRED - Not Used in Replenishment'             WHEN sil.STATUS NOT IN ('A','C')                 THEN 'SUB ITEM/LOC INACTIVE - Cannot Fulfil'             WHEN NVL(sils.STOCK_ON_HAND, 0) = 0                 THEN 'SUBSTITUTE OUT OF STOCK'             WHEN NVL(sils.STOCK_ON_HAND, 0) &gt; 0 AND sil.STATUS IN ('A','C')                 THEN 'SUBSTITUTE AVAILABLE'             ELSE 'REVIEW REQUIRED'     END                                                 AS \"Availability Status\",      sh.CREATE_DATETIME                              AS \"Record Created Datetime\"  FROM     MFCS_RDS.RDS_WV_SUB_ITEMS_DETAIL        sd      JOIN  MFCS_RDS.RDS_WV_SUB_ITEMS_HEAD    sh    ON  sd.ITEM         = sh.ITEM                                                    AND sd.LOCATION     = sh.LOCATION      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       pim   ON  sd.ITEM         = pim.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS              d     ON  pim.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS             c     ON  pim.DEPT        = c.DEPT                                                    AND pim.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc    ON  pim.DEPT        = sc.DEPT                                                    AND pim.CLASS       = sc.CLASS                                                    AND pim.SUBCLASS    = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       sim   ON  sd.SUB_ITEM     = sim.ITEM      LEFT JOIN MFCS_RDS.RDS_WV_STORE         st    ON  sd.LOCATION     = st.STORE                                                    AND sd.LOC_TYPE     = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH            wh    ON  sd.LOCATION     = wh.WH                                                    AND sd.LOC_TYPE     = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      pil   ON  sd.ITEM         = pil.ITEM                                                    AND sd.LOCATION     = pil.LOC                                                    AND sd.LOC_TYPE     = pil.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  pils  ON  sd.ITEM         = pils.ITEM                                                    AND sd.LOCATION     = pils.LOC                                                    AND sd.LOC_TYPE     = pils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      sil   ON  sd.SUB_ITEM     = sil.ITEM                                                    AND sd.LOCATION     = sil.LOC                                                        LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  sils  ON  sd.SUB_ITEM     = sils.ITEM                                                    AND sd.LOCATION     = sils.LOC                                                    AND sd.LOC_TYPE     = sils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC ril   ON  sd.ITEM         = ril.ITEM                                                    AND sd.LOCATION     = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC sril  ON  sd.SUB_ITEM     = sril.ITEM                                                    AND sd.LOCATION     = sril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS          sp    ON  ril.PRIMARY_REPL_SUPPLIER = sp.SUPPLIER  WHERE     1 = 1     ORDER BY     CASE         WHEN TRUNC(SYSDATE) &gt;= NVL(sd.START_DATE, TRUNC(SYSDATE))          AND TRUNC(SYSDATE) &lt;= NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999)         THEN 'ACTIVE'         WHEN sd.START_DATE &gt; TRUNC(SYSDATE) THEN 'FUTURE'         WHEN sd.END_DATE IS NOT NULL AND sd.END_DATE &lt; TRUNC(SYSDATE) THEN 'EXPIRED'         ELSE 'ACTIVE'     END,     d.DEPT_NAME,     c.CLASS_NAME,     pim.ITEM_DESC,     CASE sd.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END,     sim.ITEM_DESC</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Record Status</ds:name><ds